// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new Private_Bank(address(lg));
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, c.MinDeposit() + 1, type(uint128).max);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();
        // General rule: every successful deposit appends a history entry
        // whose Val equals the deposited amount.
        (, , uint256 val, ) = lg.History(0);
        assertTrue(val == amount);
    }
}
